import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';
import * as frozen from './runtime.mjs';import * as current from '../../dist/index.js';import * as old from '../0.1.0/runtime.mjs';
const out='evidence/sanitized/r2-runtime11/',read=p=>JSON.parse(fs.readFileSync(p)),sha=b=>crypto.createHash('sha256').update(b).digest('hex'),manifest=read('packages/simulation/archive/0.1.1/manifest.json');
const integrity=()=>{assert.equal(sha(fs.readFileSync(manifest.bundle.path)),manifest.bundle.sha256);for(const [p,h]of Object.entries(manifest.preservedOldArchiveHashes))assert.equal(sha(fs.readFileSync(p)),h);};integrity();assert.equal(frozen.SIMULATION_VERSION,'0.1.1');assert.equal(current.SIMULATION_VERSION,'0.1.1');assert.equal(frozen.createOperationsControllerForVersion,undefined);
const evidence={sourceCommit:manifest.sourceCommit,bundle:manifest.bundle,exports:Object.keys(frozen),workloads:[],layouts:[],legacy:[],integrity:true};
const config=read('fixtures/operations/picking-packing-burst.runconfig.json').executionConfig;
for(const name of ['picking-packing-burst','main-warehouse']){const scenario=read('fixtures/operations/'+name+'.json'),runs=[];for(const [label,mod]of [['current',current],['archive',frozen]]){const c=mod.createOperationsController({scenario,executionConfig:config});if(name==='main-warehouse')c.advanceTo(scenario.policies.run.horizonMs);else mod.runOperationsToTermination(c);const snap=c.snapshot(),report=c.exportReport(),verification=mod.recomputeOperationsReport(report);assert.equal(verification.ok,true);runs.push({label,report,snap,metrics:mod.operationsRunMetrics(snap,c.getCompletionStatus().stage)});console.log(name,label,snap.counts.shippedOrders??snap.counts);}
 assert.deepEqual(runs[0].report,runs[1].report);assert.deepEqual(runs[0].metrics,runs[1].metrics);assert.deepEqual(runs[0].snap.inventory,runs[1].snap.inventory);fs.writeFileSync(out+name+'-report.json',JSON.stringify(runs[1].report));fs.writeFileSync(out+name+'-inventory.json',JSON.stringify(runs[1].snap.inventory));evidence.workloads.push({name,semanticReportsEqual:true,metricsEqual:true,allInventoryBucketsEqual:true,metrics:runs[1].metrics,counts:runs[1].snap.counts,reportSha256:sha(JSON.stringify(runs[1].report)),inventorySha256:sha(JSON.stringify(runs[1].snap.inventory)),recomputeBoth:true});}
for(const [kind,path,fn]of [['station','evidence/sanitized/l3b/station-regression/desktop-comparison.json','verifyLayoutComparison'],['rotation','evidence/sanitized/l3c/main-rotation.json','verifyRackRotationComparison']]){const r=read(path),a=await frozen[fn](r),b=await current[fn](r);assert.deepEqual(a,b);assert.equal(typeof a==='boolean'?a:a.ok,true);evidence.layouts.push({kind,path,verification:a,currentEqual:true});console.log('layout replay',kind);}
const baseline=current.parseOperationsScenario(read('fixtures/operations/main-warehouse.json')),parent={scenarioId:baseline.id,scenarioContentSha256:await current.contentSha256(baseline),schemaVersion:baseline.schemaVersion,engineVersion:baseline.engineVersion};
for(const [kind,entityId,run,verify]of [['rack','R1','runRackLayoutComparison','verifyRackLayoutComparison'],['agent','PK-1','runAgentPlacementComparison','verifyAgentPlacementComparison']]){const input={baselineScenario:baseline,proposal:{kind:kind==='rack'?'RACK_TRANSLATION':'AGENT_INITIAL_PLACEMENT',proposalId:'archive11-'+kind,parent,entityId,target:{mode:'DELTA_MM',deltaMm:{dx:100,dz:0}}},approvedConstraints:current.defaultApprovedConstraints([entityId]),executionConfig:config,safetyCeilingMs:1000,...(kind==='rack'?{attachments:current.buildRackAttachmentMap(baseline)}:{})};const r=await current[run](input);fs.writeFileSync(out+kind+'-report.json',JSON.stringify(r));assert.equal(await frozen[verify](JSON.parse(JSON.stringify(r))),true);const a=await frozen[run](input);assert.deepEqual(a,r);evidence.layouts.push({kind,generatedReport:out+kind+'-report.json',currentEqual:true,verification:true,scope:'1000ms safety ceiling, report replay not operational completion'});console.log('layout replay',kind);}
for(const path of ['evidence/sanitized/e3-offline-comparison.json','evidence/sanitized/e4a-fixture-investigation.json']){const r=read(path),comparison=r.schema==='layoutlab.operations-investigation/1'?r.comparison:r;if(!comparison){evidence.legacy.push({path,scope:'no embedded comparison; API envelope outside frozen simulation entry'});continue;}if(comparison.versions?.simulation!=='0.1.0'){evidence.legacy.push({path,scope:'not a 0.1.0 comparison'});continue;}const oldResult=old.verifyOperationsExperiment(comparison),newResult=frozen.verifyOperationsExperiment(comparison);assert.equal(oldResult.ok,true);assert.equal(newResult.ok,false);evidence.legacy.push({path,recordedVersion:'0.1.0',oldArchiveOk:oldResult.ok,archive11RejectsWithoutRelabel:true,scope:'simulation comparison only; API envelope/provider not invoked'});console.log('legacy version respected',path);}
try{execFileSync(process.execPath,['packages/simulation/archive/build-archive11.mjs'],{stdio:'pipe'});throw Error('overwrite unexpectedly allowed');}catch(e){assert.match(String(e.stderr??e),/refusing overwrite/);evidence.overwriteRefused=true;}integrity();fs.writeFileSync(out+'proof.json',JSON.stringify(evidence,null,2));console.log('archive11 proof complete');
